package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen3Test {

    @Test
    public void testReduce_AlreadyReduced() {
        // gcd(3, 5) = 1. Should return 'this' (the same instance or equal object).
        Fraction fraction = Fraction.getFraction(3, 5);
        Fraction reduced = fraction.reduce();

        assertEquals(3, reduced.getNumerator());
        assertEquals(5, reduced.getDenominator());
        assertSame("Should return the same instance when gcd is 1", fraction, reduced);
    }










}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen3Test {



    @Test
    public void testReduce_NeedsReduction() {
        // gcd(6, 10) = 2. Should return 3/5.
        Fraction fraction = Fraction.getFraction(6, 10);
        Fraction reduced = fraction.reduce();

        assertEquals(3, reduced.getNumerator());
        assertEquals(5, reduced.getDenominator());
        assertNotSame("Should return a new instance when reduction occurs", fraction, reduced);
    }








}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen3Test {





    @Test
    public void testReduce_NegativeNumerator() {
        // gcd(abs(-6), 10) = gcd(6, 10) = 2. Result: -3/5.
        Fraction fraction = Fraction.getFraction(-6, 10);
        Fraction reduced = fraction.reduce();

        assertEquals(-3, reduced.getNumerator());
        assertEquals(5, reduced.getDenominator());
    }






}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
