import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen3Test {







    @Test
    public void testReduce_LargeCommonDivisor() {
        // gcd(100, 1000) = 100. Result: 1/10.
        Fraction fraction = Fraction.getFraction(100, 1000);
        Fraction reduced = fraction.reduce();

        assertEquals(1, reduced.getNumerator());
        assertEquals(10, reduced.getDenominator());
    }




}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen3Test {









    @Test
    public void testReduce_NumeratorIsZero() {
        // gcd(0, 5) = 5. Result: 0/1.
        // Note: Math.abs(0) is 0. gcd(0, 5) is typically 5.
        Fraction fraction = Fraction.getFraction(0, 5);
        Fraction reduced = fraction.reduce();

        assertEquals(0, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
    }


}

